const { body } = require("express-validator");
const knex = require("../../config/database");

exports.storeTopicValidator = [
  body("categoryId")
    .notEmpty()
    .withMessage("Kategori topik wajib dipilih.")
    .bail()
    .isInt()
    .withMessage("Kategori topik harus berupa angka.")
    .bail()
    .custom(async (value) => {
      const category = await knex("kmis_categories")
        .where("id", value)
        .whereNull("deleted_at")
        .first();
      if (!category) {
        throw new Error("Kategori topik yang Anda pilih tidak ditemukan.");
      }
      return true;
    }),

  body("title")
    .notEmpty()
    .withMessage("Judul topik tidak boleh kosong.")
    .bail()
    .isString()
    .withMessage("Judul topik harus berupa teks.")
    .bail()
    .isLength({ max: 255 })
    .withMessage("Judul topik maksimal 255 karakter."),

  body("description")
    .notEmpty()
    .withMessage("Deskripsi topik tidak boleh kosong.")
    .bail()
    .isString()
    .withMessage("Deskripsi topik harus berupa teks."),

  body("totalQuiz")
    .trim()
    .notEmpty()
    .withMessage("Jumlah soal pertanyaan tidak boleh kosong.")
    .bail()
    .isInt()
    .withMessage("Jumlah soal pertanyaan harus berupa angka."),

  body("quizDuration")
    .trim()
    .notEmpty()
    .withMessage("Waktu penyelesaian pertanyaan tidak boleh kosong.")
    .bail()
    .isInt()
    .withMessage(
      "Waktu penyelesaian pertanyaan harus berupa angka dan satuan detik."
    ),
];
