const { body } = require("express-validator");
const knex = require("../../config/database");

exports.storeEventValidator = [
  body("categoryId")
    .notEmpty()
    .withMessage("Kategori kegiatan wajib dipilih.")
    .bail()
    .isInt()
    .withMessage("Kategori kegiatan harus berupa angka.")
    .bail()
    .custom(async (value) => {
      const category = await knex("cms_events_categories")
        .where("id", value)
        .whereNull("deleted_at")
        .first();
      if (!category) {
        throw new Error("Kategori kegiatan yang Anda pilih tidak ditemukan.");
      }
      return true;
    }),

  body("title").custom((v) => {
    if (typeof v === "undefined")
      throw new Error("Judul kegiatan tidak boleh kosong.");
    return true;
  }),

  body("description").custom((v) => {
    if (typeof v === "undefined")
      throw new Error("Deskripsi kegiatan tidak boleh kosong.");
    return true;
  }),

  body("eventContent").custom((v) => {
    if (typeof v === "undefined")
      throw new Error("Konten kegiatan tidak boleh kosong.");
    return true;
  }),
];
